package com.example.events.service;
import com.example.events.Event;import com.example.events.repository.EventRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.List;
@Service @Transactional(readOnly=true) public class EventService {private final EventRepository events;public EventService(EventRepository events){this.events=events;}public List<Event> upcoming(String search,String category){String q=search==null?"":search.trim().toLowerCase();String c=category==null?"":category.trim();return events.findByStatusOrderByDateTimeAsc("PUBLISHED").stream().filter(e->e.dateTime.isAfter(LocalDateTime.now())).filter(e->q.isBlank()||(e.title+" "+e.description+" "+e.venue).toLowerCase().contains(q)).filter(e->c.isBlank()||c.equalsIgnoreCase(e.category)).toList();}}
